#!/usr/bin/env python3
"""Every game message type in proxy recordings, by direction and purpose group, as Markdown.

    .venv/bin/python analysis/message-breakdown.py captures/proxy-<stamp>.jsonl ... > docs/reference/message-breakdown.md

Names, confidence and groups come from traffic/protocol.py; client opcodes are resolved by
traffic/timeline.py (each connection's own S 0x32 table, the login server's rule).
"""

from __future__ import annotations

import sys
from collections import Counter, defaultdict
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from traffic.protocol import NAMES, PURPOSE, name_of, purpose_of  # noqa: E402
from traffic.timeline import messages  # noqa: E402

DIRECTIONS = {"client_to_server": "Client → server (what your game sends)",
              "server_to_client": "Server → client (what the server sends you)"}


def count(paths):
    n, size, conns = Counter(), Counter(), defaultdict(set)
    t0 = t1 = None
    for m in messages(paths):
        key = ("client_to_server" if m.side == "C" else "server_to_client", m.opcode)
        n[key] += 1
        size[key] += m.length
        conns[key].add(m.connection)
        t0 = m.time_ns if t0 is None else min(t0, m.time_ns)
        t1 = m.time_ns if t1 is None else max(t1, m.time_ns)
    all_conns = set().union(*conns.values()) if conns else set()
    return n, size, {k: len(v) for k, v in conns.items()}, len(all_conns), (t1 - t0) / 3.6e12 if n else 0


def markdown(paths):
    n, size, conns, total_conns, hours = count(paths)
    out = [f"# Every game message, by direction and purpose\n",
           f"From {', '.join(Path(p).name for p in paths)}: {sum(n.values()):,} messages over {hours:.1f} hours "
           f"on {total_conns} connections. Generated by analysis/message-breakdown.py; names and groups are "
           "traffic/protocol.py's. Confidence: confirmed = checked against what the game did; supported = "
           "the content or a strict pairing shows it; unnamed = only its group is known (from when it comes).\n"]
    for direction, title in DIRECTIONS.items():
        keys = [k for k in n if k[0] == direction]
        total = sum(n[k] for k in keys)
        if not total:   # e.g. a recording made before server messages were decoded
            continue
        named = sum(n[k] for k in keys if name_of(direction, k[1])[0])
        out.append(f"\n## {title}\n\n{total:,} messages, {sum(size[k] for k in keys) / 1e6:.1f} MB, "
                   f"{len(keys)} types; {100 * named / total:.1f}% of messages have a name.\n")
        groups = defaultdict(list)
        for k in keys:
            groups[purpose_of(direction, k[1])[0] or "not grouped yet"].append(k)
        for group, ks in sorted(groups.items(), key=lambda kv: -sum(n[k] for k in kv[1])):
            g = sum(n[k] for k in ks)
            note = next((v[1] for (d, _), v in PURPOSE.items() if v[0] == group), "")
            out.append(f"\n### {group}: {g:,} messages ({100 * g / total:.2f}%)\n\n{note}\n\n"
                       "| opcode | name | confidence | count | per hour | avg bytes | connections | what it is |\n"
                       "|---|---|---|---:|---:|---:|---:|---|")
            for k in sorted(ks, key=lambda k: -n[k]):
                op = f"0x{k[1]:x}" if k[1] is not None else "?"
                entry = NAMES.get(("C" if direction == "client_to_server" else "S", k[1]))
                name, confidence, what = entry if entry else ("", "unnamed", "")
                out.append(f"| {op} | {name} | {confidence} | {n[k]:,} | {n[k] / hours:,.0f} | "
                           f"{size[k] / n[k]:,.0f} | {conns[k]}/{total_conns} | {what.replace('|', '/')} |")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    sys.stdout.write(markdown(sys.argv[1:]))
